import csv, json
from pathlib import Path
p=Path('/workspace/logs/recorded_run')
with (p/'metrics.csv').open() as f:
 rows=list(csv.DictReader(f))
keys=['step','critic/score/mean','actor/entropy','actor/grad_norm','actor/kl_loss','actor/ppo_kl','response_length/mean','response_length/clip_ratio','response/aborted_ratio','rollout_corr/kl','rollout_corr/log_ppl_abs_diff','rollout_corr/ppl_ratio','training/rollout_actor_probs_pearson_corr','val-core/hiyouga/geometry3k/acc/mean@1','perf/time_per_step']
print('\t'.join(k.rsplit('/',1)[-1] for k in keys))
for r in rows:
 print('\t'.join(str(r[k]) for k in keys))
print('\nEvidence record schemas and distributions:')
for d in ['rollouts','validation']:
 for f in sorted((p/d).glob('*.jsonl'),key=lambda x:int(x.stem)):
  recs=[json.loads(s) for s in f.read_text().splitlines() if s.strip()]
  print(d,f.stem,'records',len(recs),'keys',sorted(set().union(*(r.keys() for r in recs))))
  for k in ['score','reward','acc']:
   vals=[r[k] for r in recs if k in r]
   if vals: print(' ',k,'mean',sum(vals)/len(vals),'nonzero',sum(v!=0 for v in vals))
  print(' output lengths',[(len(r.get('output','')),r.get('score')) for r in recs[:8]])
PY","description":"Summarize frozen metrics and evidence schemas"}

